function cohabSettingSet(id,key,value,el){const d=cohabData(id);if(!d)return;const x=cohabSettings(d);if(key==='contextLimit')x.contextLimit=Math.max(10,Math.min(80,Math.round(+value||30)));else if(key==='summaryRounds')x.summaryRounds=Math.max(0,Math.min(40,Math.round(+value||0)));else if(key==='summaryMemoryLimit')x.summaryMemoryLimit=Math.max(1,Math.min(20,Math.round(+value||8)));else if(key==='memoryCap')x.memoryCap=(String(value).trim()==='0')?0:Math.max(20,Math.min(2000,Math.round(+value||200)));else if(key==='summaryMode'&&['single','split'].includes(value))x.summaryMode=value;else if(key==='replyModel'&&['role','main','aux'].includes(value))x.replyModel=value;else if(key==='replyApiRoute'&&['follow','0','1','2','3'].includes(String(value)))x.replyApiRoute=String(value);else if(key==='summaryModel'&&['reply','main','aux'].includes(value))x.summaryModel=value;else if(key==='summaryApiRoute'&&['reply','follow','0','1','2','3'].includes(String(value)))x.summaryApiRoute=String(value);else if(key==='autoInspect')x.autoInspect=String(value)==='1'||value===true;else if(key==='autoInspectGap')x.autoInspectGap=Math.max(5,Math.min(180,Math.round(+value||30)));else if(key==='autoInspectMax')x.autoInspectMax=Math.max(0,Math.min(100,Math.round(+value||0)));else if(key==='tapAdvance'){x.tapAdvance=String(value)==='1'||value===true;if(!x.tapAdvance)cohabTapRelease();}else return;if(el&&/Limit|Rounds|Gap|Max/.test(key))el.value=x[key];const brief=document.getElementById('cohab-settings-brief');if(brief)brief.textContent=cohabSettingsBrief(d);save();}
function cohabMemoryKey(x){return encodeURIComponent([x&&x.id||'',+((x&&x.ts)||0),String(x&&x.text||'').slice(0,80)].join('|'));}
function cohabMemoryEnsureIds(d){let changed=false;(d&&d.summaries||[]).forEach(x=>{if(x&&typeof x==='object'&&!x.id){x.id=uid();changed=true;}});return changed;}
function cohabMemoryFindIndex(d,key){key=String(key||'');return(d&&d.summaries||[]).findIndex(x=>String(x&&x.id||'')===key||cohabMemoryKey(x)===key);}
/* COHAB_MEMORY_LIST_SCROLL_V1：实际滚动容器是内层记忆列表。 */
function cohabMemoryScrollTop(){const list=$('[data-cohab-memory-list]');return list?list.scrollTop:0;}
function cohabMemoryRestoreScroll(top){top=Math.max(0,+top||0);const list=$('[data-cohab-memory-list]');const restore=()=>{if(list&&list.isConnected)list.scrollTop=Math.min(top,Math.max(0,list.scrollHeight-list.clientHeight));};restore();requestAnimationFrame(()=>{restore();requestAnimationFrame(restore);});}
function cohabMemorySetImp(id,key,n){const d=cohabData(id),i=cohabMemoryFindIndex(d,key);if(!d||i<0)return;n=Math.max(1,Math.min(5,parseInt(n,10)||3));const top=cohabMemoryScrollTop();d.summaries[i].imp=n;save();cohabMemoryOpen(id,{scrollTop:top});toast('已设为 '+n+' 星');}
function cohabMemoryPrune(d,cap){if(+cap===0)return;/* 0 表示不限，交给用户自己清理 */cap=Math.max(1,+cap||200);const rows=d&&d.summaries||[];while(rows.length>cap){const i=rows.findIndex(x=>(+x.imp||3)<5);if(i<0)break;rows.splice(i,1);}return rows;}
async function cohabMemoryDelete(id,key){const d=cohabData(id);if(!d||cohabMemoryFindIndex(d,key)<0)return;const top=cohabMemoryScrollTop();if(!await uiConfirm('删除这条共同生活记忆？\n\n只删除这条总结，不会删除共同生活原聊天。'))return;const i=cohabMemoryFindIndex(d,key);if(i<0){toast('这条记忆已经不存在');return;}d.summaries.splice(i,1);save();cohabMemoryOpen(id,{scrollTop:top});toast('共同生活记忆已删除');}
