function cohabDeliverOnlineMessage(c,target,text){text=String(text||'').replace(/\s+/g,' ').trim().slice(0,500);if(!target||!text)return false;const actor=c.remark||c.name,stamp={_cohabOnline:true,_cohabOnlineBy:c.id,_cohabOnlineByName:actor};if(target.type==='role'){const m=Object.assign({role:'assistant',type:'text',content:text,time:Date.now(),id:uid()},stamp);msgs(c.id).push(m);notifyIncoming(c,m);save();if(cur().p==='chat'&&cur().id===c.id)refreshChatMessages(c.id);return true;}if(target.type==='ai-group'){const g=S.groups.find(x=>x.id===target.id);if(!g||!g.members.includes(c.id))return false;const m=Object.assign({senderId:c.id,role:'assistant',type:'text',content:text,time:Date.now(),id:uid()},stamp);g.msgs.push(m);save();gNotify(g,c);if(cur().p==='group'&&cur().id===g.id)render();return true;}return false;}
